_log = get_logger('server')

router = APIRouter(prefix='/api/task', tags=['task'])


TaskRequestUnion = Annotated[
    NormalFightRequest | EventFightRequest | CampaignRequest | ExerciseRequest | DecisiveRequest,
    Discriminator('type'),
]

# 批次 4.3：三类分级错误共用一套收口格式。前端可直接读 error_code，
# 不必再解析异常字符串；error_type/error_hint 同时写进日志。
GRADED_TASK_ERRORS = (PageDriftError, UIVersionError, DeviceError)


def _graded_error_result(error: Exception, round_num: int) -> dict[str, Any]:
    """把三类分级异常转成一轮失败结果（带稳定错误码）。"""
    info = get_graded_error_info(error)
    if info is None:  # pragma: no cover - 调用点只接三类异常
        return {'round': round_num, 'success': False, 'error': str(error)}
    _log.error(
        '[Task] 第 {} 轮: [{}] {} | {}',
        round_num,
        info['error_type'],
        info['error_hint'],
        error,
    )
    return {
        'round': round_num,
        'success': False,
        'error': _graded_error_summary(error),
        **info,
    }


def _graded_error_summary(error: Exception) -> str:
    """任务级错误摘要：始终以 ``[类型名] 提示文案`` 开头。"""
    info = get_graded_error_info(error)
    if info is None:  # pragma: no cover
        return str(error)
    return f"[{info['error_type']}] {info['error_hint']}: {error}"


def _stop_condition_value(condition: Any, name: str) -> Any:
    """读取停止条件字段（兼容 Pydantic 模型与 dict）。"""
    if condition is None:
        return None
    if isinstance(condition, dict):
        return condition.get(name)
    return getattr(condition, name, None)


def _resource_thresholds(ctx: Any) -> Any:
    """读取 daily_automation 下的资源最低保留量配置（7.9）。"""
    daily = getattr(getattr(ctx, 'config', None), 'daily_automation', None)
    return getattr(daily, 'resource_thresholds', None)


def _level_stop_reason(
    stop_condition: Any,
    results: list[dict[str, Any]],
) -> str | None:
    """按本轮结果的 ``fleet_levels`` 求值等级停止条件（5.11）。

    等级只在出征准备页识别，因此本轮打完升的级要到下一轮准备页才可见；
    命中后当前轮照常结束，只阻止下一轮启动。
    """
    # 与前端旧语义一致：只在本轮成功结束后求值等级条件，失败轮仍走失败路径。
    if not results or any(not result.get('success', False) for result in results):
        return None

    slot = _stop_condition_value(stop_condition, 'level_slot')
    target = _stop_condition_value(stop_condition, 'level_ge')
    if slot is None or target is None:
        return None
    try:
        slot = int(slot)
        target = int(target)
    except (TypeError, ValueError):
        return None
    if slot < 0 or slot > 5 or target < 1:
        return None

    observed: int | None = None
    for result in results:
        levels = result.get('fleet_levels') if isinstance(result, dict) else None
        if not isinstance(levels, dict):
            continue
        raw = levels.get(str(slot), levels.get(slot))
        try:
            level = int(raw)
        except (TypeError, ValueError):
            continue
        if level > 0 and (observed is None or level > observed):
            observed = level

    label = '旗舰' if slot == 0 else f'{slot + 1} 号位'
    if observed is None:
        _log.debug('[Task] 等级停止条件无法判断: 本轮缺少 {} 的 fleet_levels', label)
        return None
    if observed >= target:
        _log.info(
            '[Task] 等级停止条件命中: {} Lv.{} >= {}, 不再发起下一轮',
            label,
            observed,
            target,
        )
        return STOP_REASON_STOP_CONDITION
    _log.info(
        '[Task] 等级停止条件未满足: {} Lv.{} < {}, 继续下一轮',
        label,
        observed,
        target,
    )
    return None


def run_rounds(
    task_info: Any,
    round_func: Callable[[int], Any],
    times: int,
    *,
    label: str,
    total_rounds: int | None = None,
    current_node: str | None = None,
    convert: Callable[[Any, int], list[dict[str, Any]]] | None = None,
    stop_condition: Any = None,
    stop_after: Callable[[list[dict[str, Any]]], str | None] | None = None,
    resource_provider: Callable[[], Any] | None = None,
    resource_thresholds: Any = None,
) -> RoundLoopOutcome:
    """5.11：四条路由唯一的轮次原语。

    本函数只做路由层职责——停止检查、进度上报、异常结果转换、等级停止
    条件求值；真正的「船坞满轮不计数 / 解装失败即停」由
    :func:`autowsgr.ops.rounds.run_round_loop` 统一实现，
    ``ops.normal_fight.run_for_times`` 复用同一份底座。

    Parameters
    ----------
    task_info:
        ``TaskManager`` 启动快照，仅用于日志定位。
    round_func:
        执行一轮；参数为当前计数的轮次（1-based）。
    times:
        需要完成的真实轮次。
    label:
        日志前缀，如 ``常规战`` / ``活动战`` / ``战役`` / ``决战``。
    total_rounds:
        上报给日志的总轮次；默认等于 ``times``。
    current_node:
        进度上报里的节点名（决战用 ``决战``）。
    convert:
        ``(raw_result, current_round)`` → 结果 dict 列表；默认按
        ``convert_combat_result`` 转换单场战斗结果。
    stop_condition:
        请求里的停止条件；本轮只求值 ``level_slot`` / ``level_ge``。
    stop_after:
        额外停止谓词（决战 LEAVE/ERROR 用），返回非空即终止。
    resource_provider:
        返回当前资源快照（通常是 ``ctx.resources``）；与
        ``resource_thresholds`` 同时提供才启用 7.9 轮前资源检查。
    resource_thresholds:
        油/弹/钢/铝最低保留量（通常来自
        ``config.daily_automation.resource_thresholds``）。
    """
    task_id = getattr(task_info, 'task_id', '-')
    total = total_rounds if total_rounds is not None else times

    resource_violation: list[str] = []

    def _resource_guard(_round_num: int) -> str | None:
        if resource_provider is None or resource_thresholds is None:
            return None
        try:
            resources = resource_provider()
        except Exception as error:  # noqa: BLE001 - 读取失败不应中断任务
            _log.warning('[Task] 读取资源快照失败，跳过阈值判断: {}', error)
            return None
        violation = evaluate_resource_thresholds(resources, resource_thresholds)
        if violation is None:
            return None
        resource_violation.append(violation)
        _log.warning('[Task] {}资源低于阈值: {}，中止剩余轮次', label, violation)
        return STOP_REASON_RESOURCE_EXHAUSTED

    def _on_round_start(current: int, _total: int) -> None:
        task_manager.update_progress(current_round=current, current_node=current_node)
        _log.info('[Task] {}第 {}/{} 轮 (task={})', label, current, total, task_id)

    def _normalize(raw: Any, round_num: int) -> list[dict[str, Any]]:
        if convert is not None:
            return convert(raw, round_num)
        return [convert_combat_result(raw, round_num)]

    def _on_round_complete(results: list[dict[str, Any]]) -> None:
        for result in results:
            task_manager.add_result(result)

    def _on_exception(error: Exception, round_num: int) -> ExceptionDecision:
        if isinstance(error, TaskStopRequested):
            # 用户主动停止不是失败：静默中止剩余轮次，不计入失败统计。
            _log.info(
                '[Task] {}收到停止请求, 中止剩余轮次 (第 {} 轮未完成)',
                label,
                round_num,
            )
            return ExceptionDecision(
                break_loop=True,
                stop_reason=STOP_REASON_STOPPED,
                count_round=False,
            )
        if isinstance(error, PageNotRecognizedError):
            _log.error(
                '[Task] {}第 {} 轮: 页面无法识别, 已中止。现场截图: {}',
                label,
                round_num,
                error.screenshot_path or '未保存',
            )
            return ExceptionDecision(
                results=[{
                    'round': round_num,
                    'success': False,
                    'unknown_page': True,
                    'error': str(error),
                    'screenshot': error.screenshot_path,
                }],
                break_loop=True,
                stop_reason=STOP_REASON_UNKNOWN_PAGE,
                error=str(error),
                count_round=False,
            )
        if isinstance(error, GRADED_TASK_ERRORS):
            # 4.3 分级错误：页面漂移 / UI 版本 / 设备故障，带 error_code 中止。
            return ExceptionDecision(
                results=[_graded_error_result(error, round_num)],
                break_loop=True,
                stop_reason=STOP_REASON_ERROR,
                error=_graded_error_summary(error),
                count_round=False,
            )
        _log.error('[Task] {}第 {} 轮失败: {}', label, round_num, error)
        return ExceptionDecision(
            results=[{'round': round_num, 'success': False, 'error': str(error)}],
            break_loop=False,
            count_round=True,
        )

    def _stop_after(results: list[dict[str, Any]]) -> str | None:
        if stop_after is not None:
            reason = stop_after(results)
            if reason:
                return reason
        return _level_stop_reason(stop_condition, results)

    outcome = run_round_loop(
        round_func,
        times,
        stop_requested=task_manager.should_stop,
        on_round_start=_on_round_start,
        each_round_guard=_resource_guard,
        normalize=_normalize,
        on_round_complete=_on_round_complete,
        on_exception=_on_exception,
        stop_after=_stop_after,
    )
    if outcome.stop_reason == STOP_REASON_RESOURCE_EXHAUSTED and resource_violation:
        return RoundLoopOutcome(
            results=outcome.results,
            stop_reason=outcome.stop_reason,
            error=f'资源低于配置阈值: {resource_violation[-1]}',
        )
    return outcome


@router.post('/start', response_model=ApiResponse)
async def task_start(request: TaskRequestUnion) -> ApiResponse:  # type: ignore[arg-type]
    """启动任务 (异步执行，立即返回)。"""
    # 5.4：非 ready 立刻 503。这一步必须在抢 lifecycle_lock 之前，
    # 否则启动中的请求会把任务请求一起挂住最多 300s。
    ensure_system_ready()

    # 已经有一个任务在跑时不必再做设备探活，直接 409。
    if task_manager.is_running:
        raise api_error(409, ErrorCode.TASK_RUNNING, '已有任务正在运行')

    # 5.10：READY 只代表启动过；模拟器被手动关掉后仍可能是 READY。
    # 任务准入先做一次真实探活，避免「请求 200、任务线程异步失败」。
    if not await is_emulator_alive():
        raise api_error(
            503,
            ErrorCode.DEVICE_UNAVAILABLE,
            '模拟器连接已断开，请先重新启动系统',
        )

    async with lifecycle_lock:
        # 排队期间系统可能已进入 starting/stopping，拿到锁后复核一次。
        ensure_system_ready()

        if task_manager.is_running:
            raise api_error(409, ErrorCode.TASK_RUNNING, '已有任务正在运行')

        try:
            ctx = get_context()
        except RuntimeError as e:
            raise api_error(503, ErrorCode.SYSTEM_NOT_READY, str(e)) from e

        ctx.stop_event = task_manager.stop_event

        # 4.5：新一轮任务启动时强制推一次空基线，前端回到「识别中」，
        # 不会把上一轮最后停留的页面当成当前状态。
        reset_ui_state = getattr(ctx, 'reset_ui_state', None)
        if callable(reset_ui_state):
            reset_ui_state()

        try:
            if isinstance(request, NormalFightRequest):
                return await _start_normal_fight(ctx, request)
            elif isinstance(request, EventFightRequest):
                return await _start_event_fight(ctx, request)
            elif isinstance(request, CampaignRequest):
                return await _start_campaign(ctx, request)
            elif isinstance(request, ExerciseRequest):
                return await _start_exercise(ctx, request)
            elif isinstance(request, DecisiveRequest):
                return await _start_decisive(ctx, request)
            else:
                raise api_error(400, ErrorCode.INVALID_REQUEST, '未知的任务类型')
        except DeviceOperationBusyError as error:
            raise api_error(
                409,
                ErrorCode.DEVICE_BUSY,
                str(error),
                headers={'Retry-After': '1'},
            ) from error


@router.post('/stop', response_model=ApiResponse)
async def task_stop() -> ApiResponse:
    """停止当前任务。"""
    if not task_manager.is_running:
        return ApiResponse(success=True, message='没有正在运行的任务')

    success = task_manager.stop_task()
    if success:
        return ApiResponse(
            success=True,
            data={
                'task_id': task_manager.current_task.task_id,
                'status': 'stopped',
            },
            message='已请求停止任务',
        )
    else:
        raise api_error(409, ErrorCode.TASK_STOP_FAILED, '停止失败')


@router.get(
    '/status',
    response_model=ApiResponse[TaskStatusResponse],
    response_model_exclude_unset=True,
)
async def task_status() -> ApiResponse[TaskStatusResponse]:
    """查询当前任务状态。"""
    status = task_manager.get_status()
    return ApiResponse[TaskStatusResponse](success=True, data=status)


# ═══════════════════════════════════════════════════════════════════════════════
# 任务启动辅助
# ═══════════════════════════════════════════════════════════════════════════════


async def _start_normal_fight(ctx: Any, request: NormalFightRequest) -> ApiResponse:
    """启动常规战任务。"""
    from autowsgr.combat import CombatPlan
    from autowsgr.ops import run_normal_fight

    def executor(task_info: Any) -> TaskOutcome:
        if request.plan_id:
            plan = CombatPlan.from_yaml(request.plan_id)
        elif request.plan:
            plan = build_combat_plan(request.plan)
        else:
            raise ValueError('必须提供 plan 或 plan_id')

        # API plan 覆盖 YAML 舰队；DTO 在 runner 启动前转换成领域模型。
        fleet_selection = build_fleet_selection(plan, request.plan)

        def _round_once(_round: int) -> Any:
            battles = run_normal_fight(
                ctx,
                plan,
                times=1,
                fleet_selection=fleet_selection,
            )
            if not battles:
                raise RuntimeError('常规战未返回战斗结果')
            return battles[0]

        outcome = run_rounds(
            task_info,
            _round_once,
            request.times,
            label='常规战',
            total_rounds=request.times,
            stop_condition=request.stop_condition,
            resource_provider=lambda: ctx.resources,
            resource_thresholds=_resource_thresholds(ctx),
        )
        return TaskOutcome.from_results(
            outcome.results,
            error=outcome.error,
            stop_reason=outcome.stop_reason,
        )

    task_id = task_manager.start_task(
        task_type='normal_fight',
        total_rounds=request.times,
        executor=executor,
    )

    return ApiResponse(
        success=True,
        data={'task_id': task_id, 'status': 'running'},
        message='任务已启动',
    )


async def _start_event_fight(ctx: Any, request: EventFightRequest) -> ApiResponse:
    """启动活动战任务。"""
    from autowsgr.combat import CombatPlan
    from autowsgr.ops import run_event_fight

    def executor(task_info: Any) -> TaskOutcome:
        if request.plan_id:
            plan = CombatPlan.from_yaml(request.plan_id)
        elif request.plan:
            plan = build_combat_plan(request.plan)
        else:
            raise ValueError('必须提供 plan 或 plan_id')

        # 活动战顶层 fleet_id 优先，其余覆盖规则与普通战完全一致。
        fleet_selection = build_fleet_selection(
            plan,
            request.plan,
            fleet_id=request.fleet_id,
        )

        def _round_once(_round: int) -> Any:
            battles = run_event_fight(
                ctx,
                plan,
                times=1,
                fleet_selection=fleet_selection,
            )
            if not battles:
                raise RuntimeError('活动战未返回战斗结果')
            return battles[0]

        outcome = run_rounds(
            task_info,
            _round_once,
            request.times,
            label='活动战',
            total_rounds=request.times,
            stop_condition=request.stop_condition,
            resource_provider=lambda: ctx.resources,
            resource_thresholds=_resource_thresholds(ctx),
        )
        return TaskOutcome.from_results(
            outcome.results,
            error=outcome.error,
            stop_reason=outcome.stop_reason,
        )

    task_id = task_manager.start_task(
        task_type='event_fight',
        total_rounds=request.times,
        executor=executor,
    )

    return ApiResponse(
        success=True,
        data={'task_id': task_id, 'status': 'running'},
        message='任务已启动',
    )


async def _start_campaign(ctx: Any, request: CampaignRequest) -> ApiResponse:
    """启动战役任务。"""
    from autowsgr.ops import CampaignRunner
    from autowsgr.types import Formation, RepairMode

    def executor(task_info: Any) -> TaskOutcome:
        # 阵型/修理由任务预设逐条指定；未指定时保留 CampaignRunner 自身默认。
        overrides: dict[str, Any] = {}
        if request.formation is not None:
            overrides['formation'] = Formation(request.formation)
        if request.repair_mode is not None:
            overrides['repair_mode'] = RepairMode(request.repair_mode)

        runner = CampaignRunner(
            ctx,
            campaign_name=request.campaign_name,
            times=1,
            **overrides,
        )

        def _round_once(_round: int) -> list[Any]:
            return runner.run()

        def _convert(raw: list[Any], round_num: int) -> list[dict[str, Any]]:
            if not raw:
                return [{
                    'round': round_num,
                    'success': False,
                    'error': '战役未返回任何战斗结果',
                }]
            base = (round_num - 1) * len(raw)
            return [
                convert_combat_result(result, base + index + 1)
                for index, result in enumerate(raw)
            ]

        outcome = run_rounds(
            task_info,
            _round_once,
            request.times,
            label='战役',
            total_rounds=request.times,
            convert=_convert,
            stop_condition=request.stop_condition,
            resource_provider=lambda: ctx.resources,
            resource_thresholds=_resource_thresholds(ctx),
        )
        return TaskOutcome.from_results(
            outcome.results,
            error=outcome.error,
            stop_reason=outcome.stop_reason,
        )

    task_id = task_manager.start_task(
        task_type='campaign',
        total_rounds=request.times,
        executor=executor,
    )

    return ApiResponse(
        success=True,
        data={'task_id': task_id, 'status': 'running'},
        message='任务已启动',
    )


async def _start_exercise(ctx: Any, request: ExerciseRequest) -> ApiResponse:
    """启动演习任务。"""
    from autowsgr.ops import ExerciseRunner
    from autowsgr.types import Formation, RepairMode

    def executor(_task_info: Any) -> TaskOutcome:
        overrides: dict[str, Any] = {}
        if request.formation is not None:
            overrides['formation'] = Formation(request.formation)
        if request.repair_mode is not None:
            overrides['repair_mode'] = RepairMode(request.repair_mode)

        runner = ExerciseRunner(ctx, fleet_id=request.fleet_id, **overrides)
        task_manager.update_progress(current_round=1, current_node='演习')

        try:
            results = runner.run()
            return TaskOutcome.from_results(
                [convert_combat_result(r, i + 1) for i, r in enumerate(results)]
            )
        except TaskStopRequested:
            _log.info('[Task] 演习: 收到停止请求')
            return TaskOutcome.from_results([])
        except PageNotRecognizedError as e:
            _log.error('[Task] 演习: 页面无法识别, 现场截图: {}', e.screenshot_path or '未保存')
            return TaskOutcome.from_results([{
                'round': 1,
                'success': False,
                'unknown_page': True,
                'error': str(e),
                'screenshot': e.screenshot_path,
            }])
        except (PageDriftError, UIVersionError, DeviceError) as e:
            return TaskOutcome.from_results(
                [_graded_error_result(e, 1)],
                error=_graded_error_summary(e),
            )
        except Exception as e:
            return TaskOutcome.from_results([{'round': 1, 'success': False, 'error': str(e)}])

    task_id = task_manager.start_task(
        task_type='exercise',
        total_rounds=1,
        executor=executor,
    )

    return ApiResponse(
        success=True,
        data={'task_id': task_id, 'status': 'running'},
        message='任务已启动',
    )


async def _start_decisive(ctx: Any, request: DecisiveRequest) -> ApiResponse:
    """启动决战任务。"""
    from autowsgr.infra import DecisiveConfig
    from autowsgr.ops import DecisiveController

    def executor(task_info: Any) -> TaskOutcome:
        config = DecisiveConfig(
            chapter=request.chapter,
            decisive_rounds=request.decisive_rounds,
            use_new_fleet_change_algorithm=request.use_new_fleet_change_algorithm,
            level1=request.level1,
            level2=request.level2,
            flagship_priority=request.flagship_priority,
            use_quick_repair=request.use_quick_repair,
        )

        controller = DecisiveController(ctx, config)

        def _round_once(_round: int) -> Any:
            return controller.run()

        def _convert(raw: Any, round_num: int) -> list[dict[str, Any]]:
            is_error = raw.value == 'error'
            converted: dict[str, Any] = {
                'round': round_num,
                'success': not is_error,
                'result': raw.value,
            }
            if is_error:
                detail = getattr(controller, 'last_error', None) or '未知错误'
                # 前端 SchedulerTaskPolicy 只把包含“需要进行手动修理”的错误
                # 视为不可重试终态：踢出逻辑任务，等待用户手动处理。
                converted['error'] = f'决战执行失败，需要进行手动修理: {detail}'
            return [converted]

        def _stop_after(results: list[dict[str, Any]]) -> str | None:
            for result in results:
                value = result.get('result')
                if value in {'leave', 'error'}:
                    _log.warning(
                        '[Task] 决战第 {} 轮终止: {}',
                        result.get('round'),
                        value,
                    )
                    return 'leave' if value == 'leave' else STOP_REASON_ERROR
            return None

        outcome = run_rounds(
            task_info,
            _round_once,
            request.decisive_rounds,
            label='决战',
            total_rounds=request.decisive_rounds,
            current_node='决战',
            convert=_convert,
            stop_after=_stop_after,
            resource_provider=lambda: ctx.resources,
            resource_thresholds=_resource_thresholds(ctx),
        )
        return TaskOutcome.from_results(
            outcome.results,
            error=outcome.error,
            stop_reason=outcome.stop_reason,
        )

    task_id = task_manager.start_task(
        task_type='decisive',
        total_rounds=request.decisive_rounds,
        executor=executor,
    )

    return ApiResponse(
        success=True,
        data={'task_id': task_id, 'status': 'running'},
        message='任务已启动',
    )
